import auth, {
  GoogleAuthProvider,
  FacebookAuthProvider,
} from "@react-native-firebase/auth";
import { GoogleSignin } from "@react-native-google-signin/google-signin";
import { AccessToken, LoginManager } from "react-native-fbsdk-next";
import { AuthService } from "../AuthService";

// Mock Google Sign-In
jest.mock("@react-native-google-signin/google-signin", () => ({
  GoogleSignin: {
    configure: jest.fn(),
    hasPlayServices: jest.fn().mockResolvedValue(true),
    signIn: jest.fn(),
  },
  statusCodes: { PLAY_SERVICES_NOT_AVAILABLE: "PLAY_SERVICES_NOT_AVAILABLE" },
}));

// Mock Facebook SDK
jest.mock("react-native-fbsdk-next", () => ({
  LoginManager: {
    logInWithPermissions: jest.fn(),
  },
  AccessToken: {
    getCurrentAccessToken: jest.fn(),
  },
}));

// Mock React Native InteractionManager
jest.mock("react-native", () => ({
  InteractionManager: {
    runAfterInteractions: jest.fn((callback) => {
      // Run callback immediately in tests
      return Promise.resolve().then(callback);
    }),
  },
}));

const mockFirebaseAuthUser = { uid: "test-uid", email: "test@example.com" };

describe("AuthService", () => {
  const mockEmail = "test@example.com";
  const mockPassword = "password123";
  const mockUserCredential = { user: { uid: "test-uid" } } as any;

  beforeEach(() => {
    jest.clearAllMocks();

    // Get the auth instance from the global mock
    const authInstance = auth();

    // Setup auth instance mocks
    (
      authInstance.createUserWithEmailAndPassword as jest.Mock
    ).mockResolvedValue(mockUserCredential);
    (authInstance.signInWithEmailAndPassword as jest.Mock).mockResolvedValue(
      mockUserCredential
    );
    (authInstance.sendPasswordResetEmail as jest.Mock).mockResolvedValue(
      undefined
    );
    (authInstance.signOut as jest.Mock).mockResolvedValue(undefined);
    (authInstance.signInWithCredential as jest.Mock).mockResolvedValue(
      mockUserCredential
    );

    // Setup Google and Facebook credential mocks (these are already set up in global mock)
    // No need to mock them again here

    // Mock GoogleSignin specifics
    (GoogleSignin.signIn as jest.Mock).mockResolvedValue({
      data: { idToken: "mockGoogleIdToken" },
      user: { email: "user@google.com" },
    });

    // Mock Facebook specifics
    (LoginManager.logInWithPermissions as jest.Mock).mockResolvedValue({
      isCancelled: false,
      grantedPermissions: ["email"],
    });
    (AccessToken.getCurrentAccessToken as jest.Mock).mockResolvedValue({
      accessToken: "mockFbAccessToken",
    });
  });

  describe("signUpWithEmail", () => {
    it("should call createUserWithEmailAndPassword and return user credential", async () => {
      const result = await AuthService.signUpWithEmail(mockEmail, mockPassword);

      const authInstance = auth();
      expect(authInstance.createUserWithEmailAndPassword).toHaveBeenCalledWith(
        mockEmail,
        mockPassword
      );
      expect(result).toEqual(mockUserCredential);
    });

    it("should throw an error if createUserWithEmailAndPassword fails", async () => {
      const errorMessage = "Sign up failed";
      const authInstance = auth();
      (
        authInstance.createUserWithEmailAndPassword as jest.Mock
      ).mockRejectedValueOnce(new Error(errorMessage));

      await expect(
        AuthService.signUpWithEmail(mockEmail, mockPassword)
      ).rejects.toThrow(errorMessage);
    });
  });

  describe("loginWithEmail", () => {
    it("should call signInWithEmailAndPassword and return user credential", async () => {
      const result = await AuthService.loginWithEmail(mockEmail, mockPassword);

      const authInstance = auth();
      expect(authInstance.signInWithEmailAndPassword).toHaveBeenCalledWith(
        mockEmail,
        mockPassword
      );
      expect(result).toEqual(mockUserCredential);
    });

    it("should throw an error if signInWithEmailAndPassword fails", async () => {
      const errorMessage = "Login failed";
      const authInstance = auth();
      (
        authInstance.signInWithEmailAndPassword as jest.Mock
      ).mockRejectedValueOnce(new Error(errorMessage));

      await expect(
        AuthService.loginWithEmail(mockEmail, mockPassword)
      ).rejects.toThrow(errorMessage);
    });
  });

  describe("sendPasswordResetEmail", () => {
    it("should call sendPasswordResetEmail", async () => {
      await AuthService.sendPasswordResetEmail(mockEmail);

      const authInstance = auth();
      expect(authInstance.sendPasswordResetEmail).toHaveBeenCalledWith(
        mockEmail
      );
    });

    it("should throw an error if sendPasswordResetEmail fails", async () => {
      const errorMessage = "Reset email failed";
      const authInstance = auth();
      (authInstance.sendPasswordResetEmail as jest.Mock).mockRejectedValueOnce(
        new Error(errorMessage)
      );

      await expect(
        AuthService.sendPasswordResetEmail(mockEmail)
      ).rejects.toThrow(errorMessage);
    });
  });

  describe("logout", () => {
    it("should call signOut", async () => {
      await AuthService.logout();

      const authInstance = auth();
      expect(authInstance.signOut).toHaveBeenCalledTimes(1);
    });

    it("should throw an error if signOut fails", async () => {
      const errorMessage = "Sign out failed";
      const authInstance = auth();
      (authInstance.signOut as jest.Mock).mockRejectedValueOnce(
        new Error(errorMessage)
      );

      await expect(AuthService.logout()).rejects.toThrow(errorMessage);
    });
  });
});
